def transform(grid):
    # What if the rule is: find the intruder / anomaly / asymmetry across both axes?
    R, C = len(grid), len(grid[0])
    mid_r, mid_c = R // 2, C // 2
    res = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            # check symmetry
            sym_r = R - 1 - r
            sym_c = C - 1 - c
            if grid[r][c] != grid[sym_r][c] or grid[r][c] != grid[r][sym_c]:
                res[r][c] = grid[r][c]
    return res
